#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define HASH_SIZE 2097152 // 2^21
#define HASH_MASK (HASH_SIZE - 1)

#define FLAG_PREFIX    1
#define FLAG_SUFFIX    2
#define FLAG_SUBSTRING 4

typedef struct {
    uint64_t key;
    uint8_t flags;
} HashEntry;

static HashEntry table[HASH_SIZE];

static inline uint64_t hash64(uint64_t x) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

static inline uint64_t encode(const char *s, int len) {
    uint64_t code = 0;
    for (int i = 0; i < len; i++) {
        code = (code << 5) | (uint64_t)(s[i] - 'a' + 1);
    }
    return code;
}

static void insert(uint64_t key, uint8_t flag) {
    uint32_t idx = (uint32_t)(hash64(key) & HASH_MASK);
    while (table[idx].key != 0 && table[idx].key != key) {
        idx = (idx + 1) & HASH_MASK;
    }
    table[idx].key = key;
    table[idx].flags |= flag;
}

static uint8_t lookup(uint64_t key) {
    uint32_t idx = (uint32_t)(hash64(key) & HASH_MASK);
    while (table[idx].key != 0) {
        if (table[idx].key == key) {
            return table[idx].flags;
        }
        idx = (idx + 1) & HASH_MASK;
    }
    return 0;
}

static char S[10005][20];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", S[i]);
    }

    for (int i = 0; i < n; i++) {
        int len = (int)strlen(S[i]);

        if (i > 0) {
            uint64_t full_key = encode(S[i], len);
            if (lookup(full_key) & FLAG_SUBSTRING) {
                printf("%s\n", S[i]);
                return 0;
            }

            bool invalid = false;
            for (int L = 1; L < len; L++) {
                uint64_t left_key = encode(S[i], L);
                if (lookup(left_key) & FLAG_SUFFIX) {
                    uint64_t right_key = encode(S[i] + L, len - L);
                    if (lookup(right_key) & FLAG_PREFIX) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                printf("%s\n", S[i]);
                return 0;
            }
        }

        // Adiciona todos os prefixos de S[i]
        for (int L = 1; L <= len; L++) {
            insert(encode(S[i], L), FLAG_PREFIX);
        }

        // Adiciona todos os sufixos de S[i]
        for (int start = 0; start < len; start++) {
            insert(encode(S[i] + start, len - start), FLAG_SUFFIX);
        }

        // Adiciona todas as substrings de S[i]
        for (int start = 0; start < len; start++) {
            for (int L = 1; start + L <= len; L++) {
                insert(encode(S[i] + start, L), FLAG_SUBSTRING);
            }
        }
    }

    printf("ok\n");
    return 0;
}
